style.css:
@-moz-document domain("roblox.com") {
/* Inject the video background */
  html::before {
    content: "";
    position: fixed;
    top: 0;
    left: 0;
    width: 100vw;
    height: 100vh;
    z-index: -1;
    background: black;
  }

  body::after {
    content: "";
    position: fixed;
    top: 0;
    left: 0;
    width: 100vw;
    height: 100vh;
    z-index: -2;
    pointer-events: none;
    background: url("https://cdn.openai.com/chatgpt/temp/roblox-bg.mp4") no-repeat center center fixed;
    background-size: cover;
  }

  body {
    background-color: transparent !important;
  }

  /* Optional: Make roblox cards and nav semi-transparent */
  .game-card-container, .navbar, .nav-container {
    background-color: rgba(18, 18, 18, 0.6) !important;
    backdrop-filter: blur(4px);
  }
}
